struct Data {};
using SP = std::shared_ptr<Data>;

std::atomic<SP> atomic_p(std::make_shared<Data>());
SP incoming_p(std::make_shared<Data>());

// atomic_exchange implementation analysis:
// Requirement: Atomically swap the pointer and control block (128 bits).
// Requirement: Atomic Ref Count updates for both pointers.

// 1. incoming_p ref count is incremented (non-atomically w.r.t the store).
// 2. Atomic 128-bit Compare-and-Swap (CAS2/DCAS) or internal lock.
// 3. returned_old ref count is decremented (non-atomically w.r.t the load).

SP returned_old = atomic_p.exchange(
    incoming_p,
    std::memory_order_acq_rel
);

// Lock-free check:
// std::atomic_is_lock_free(&atomic_p)
